xql_query:
// ============================================================
// Rule: MS_EntraID Add User Outside Detected
// Vendor: Microsoft EntraID
// Objective:
// Detect activity associated with MS_EntraID Add User Outside Detected.
// Severity: SEV_030_MEDIUM
// Category: PRIVILEGE_ESCALATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1098 - Account Manipulation
// Technique: T1136.003 - Create Account: Cloud Account
// Technique: T1556 - Modify Authentication Process

dataset = msft_azure_raw
| alter
    timestamp = _time,
    operationName = properties -> operationName,
    userPrincipalName = properties -> userPrincipalName,
    userDisplayName = properties -> userDisplayName,
    userId = properties -> userId,
    ipAddress = properties -> ipAddress,
    city = properties -> location.city,
    state = properties -> location.state,
    countryOrRegion = properties -> location.countryOrRegion,
    appDisplayName = properties -> appDisplayName,
    resultType = properties -> resultType,
    resultDescription = properties -> resultDescription,
    userAgent = properties -> userAgent,
    category = properties -> category

// Detect addition of user to role outside of PIM
| filter category = "RoleManagement"
    and operationName = "Add member to role outside of PIM (permanent)"
    and resultType = "0"

| fields timestamp, operationName, userPrincipalName, userDisplayName, userId, ipAddress, city, state, countryOrRegion, userAgent, appDisplayName, resultType, resultDescription
